#include <cstdio>

#include "../tests/subchain_vectors.hpp"

int main() {
  if (aviary_init() != 0) return 1;
  std::printf(
      "# Aviary golden vectors - subchains version 2 (dynamic registration,\n"
      "# Merkle registry, closing, persistence). docs/design/SUBCHAINS.md Part 2.\n"
      "#\n"
      "# Generated by tools/print_subchain_vectors.cpp, which runs the scenario in\n"
      "# tests/subchain_vectors.hpp through the C ABI. The C++ suite\n"
      "# (test_subchain_vectors), the Go binding and the Dart binding replay the\n"
      "# same calls and must reproduce every line exactly.\n"
      "#\n"
      "# Scenario. Keys: registrar and record author = the Ed25519 key from the\n"
      "# seed 32 x 0xA0 (registrar_secret below, seed || public); main chain\n"
      "# validator = BLS key from 32 x 0x01; user chain validator = BLS key from\n"
      "# 32 x 0x10. Every genesis is aviary_genesis_build(chain_id, timestamp 1,\n"
      "# assurance 1, state model 2, no accounts, one validator of power 1) with\n"
      "# the blueprint bft / record.\n"
      "#   main chain 1: dynamic policy (max_depth 1, no other bound, threshold 1,\n"
      "#     one Ed25519 registrar, no genesis children).\n"
      "#   user chain 1001: bound to the main chain's genesis hash.\n"
      "#   main block 1 (timestamp 10): registers chain 1001 (epoch 0, no expiry).\n"
      "#   user blocks 1 and 2 (timestamps 20, 21): block 1 writes key 32 x 0x42 =\n"
      "#     \"door opened\" (nonce 0, op 0).\n"
      "#   main block 2 (timestamp 11): anchors both user headers.\n"
      "#   main block 3 (timestamp 12): closes chain 1001 at its recorded tip.\n"
      "#   wide chain 2: same policy; block 1 (timestamp 10) registers chains 2000\n"
      "#     to 2010, each with the user validator; the proof is for chain 2007.\n"
      "# *_hash of a snapshot is BLAKE3-256 of the aviary_chain_snapshot bytes,\n"
      "# taken with the block archive enabled from genesis on both chains.\n"
      "#\n"
      "# Format: <name> <hex>\n\n");
  for (const auto& [name, value] : subchain_vectors::compute()) std::printf("%s %s\n", name.c_str(), value.c_str());
  return 0;
}
